<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$a=$_POST['action']??'';if($a==='bulk_add'){ $rows=json_decode($_POST['rows']??'[]',true)?:[]; if(!$rows)throw new RuntimeException('Add at least one supplier.');$db->beginTransaction();$q=$db->prepare('INSERT INTO suppliers(name,phone,address) VALUES(?,?,?)');$n=0;foreach($rows as $r){$name=trim((string)($r['name']??''));if($name==='')continue;$q->execute([$name,trim((string)($r['phone']??'')),trim((string)($r['address']??''))]);$n++;}$db->commit();header('Location: suppliers.php?saved='.$n);exit;}if($a==='pay'){$sid=(int)$_POST['supplier_id'];$amount=(float)$_POST['amount'];$note=trim((string)($_POST['note']??''));if($amount<=0)throw new RuntimeException('Enter a valid payment amount.');$q=$db->prepare('SELECT COALESCE(SUM(subtotal-paid),0) FROM purchases WHERE supplier_id=?');$q->execute([$sid]);$due=(float)$q->fetchColumn();if($amount>$due+0.0001)throw new RuntimeException('Payment cannot exceed outstanding balance.');$db->beginTransaction();$remaining=$amount;$q=$db->prepare('SELECT id,subtotal,paid FROM purchases WHERE supplier_id=? AND subtotal>paid ORDER BY id');$q->execute([$sid]);$first=null;foreach($q as $p){$open=(float)$p['subtotal']-(float)$p['paid'];$take=min($remaining,$open);if($take>0){if($first===null)$first=(int)$p['id'];$db->prepare('UPDATE purchases SET paid=paid+? WHERE id=?')->execute([$take,$p['id']]);$remaining-=$take;}if($remaining<=0)break;}$db->prepare('INSERT INTO supplier_payments(supplier_id,purchase_id,amount,note) VALUES(?,?,?,?)')->execute([$sid,$first,$amount,$note!==''?$note:null]);$db->commit();audit_log('supplier_payment','Supplier #'.$sid.' payment Rs. '.number_format($amount,2));header('Location: suppliers.php?paid=1');exit;}}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}$rows=$db->query('SELECT s.*,COALESCE((SELECT SUM(p.subtotal-p.paid) FROM purchases p WHERE p.supplier_id=s.id),0) due,COALESCE((SELECT SUM(p.subtotal) FROM purchases p WHERE p.supplier_id=s.id),0) purchases_total FROM suppliers s ORDER BY s.name')->fetchAll();$payments=$db->query('SELECT sp.*,s.name supplier,p.invoice_no FROM supplier_payments sp JOIN suppliers s ON s.id=sp.supplier_id LEFT JOIN purchases p ON p.id=sp.purchase_id ORDER BY sp.id DESC LIMIT 100')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Suppliers</title><link rel="stylesheet" href="style.css"><style>.bulk{overflow:auto}.bulk table{min-width:700px}.bulk input{width:100%;box-sizing:border-box;padding:8px;border:1px solid #cbd5e1;border-radius:6px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}.pay{display:flex;gap:6px}.pay input{width:110px;padding:8px}.remove{border:0;background:none;color:#dc2626;font-size:20px;cursor:pointer}</style></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a class="active" href="manage.php">Management</a></nav><div class="user-info">👤 <?=e(current_user()['username']??'')?> · <a href="logout.php">Logout</a></div></header><main><div class="page-title"><div><div class="eyebrow">SUPPLIERS</div><h1>Suppliers</h1><p>Add multiple suppliers quickly, then manage balances and payments below.</p></div></div><?php if($error):?><div class="error">✕ <?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="success">✓ <?=e($_GET['saved'])?> suppliers saved.</div><?php endif;?><?php if(isset($_GET['paid'])):?><div class="success">✓ Supplier payment recorded.</div><?php endif;?><section class="panel"><h2>➕ Bulk Add Suppliers</h2><div class="bulk"><table><thead><tr><th>Name *</th><th>Phone</th><th>Address</th><th></th></tr></thead><tbody id="new"></tbody></table></div><div class="actions"><button type="button" class="btn" id="add">＋ Add Row</button><button type="button" class="btn" id="save">💾 Save All Suppliers</button></div></section><section class="panel"><h2>Supplier Balances</h2><div class="bulk"><table><tr><th>Supplier</th><th>Phone</th><th>Total Purchases</th><th>Outstanding</th><th>Pay Supplier</th></tr><?php foreach($rows as $r):$due=(float)$r['due'];?><tr><td><b><?=e($r['name'])?></b></td><td><?=e($r['phone'])?></td><td>Rs. <?=money((float)$r['purchases_total'])?></td><td><b>Rs. <?=money($due)?></b></td><td><?php if($due>0):?><form method="post" class="pay"><input type="hidden" name="action" value="pay"><input type="hidden" name="supplier_id" value="<?=$r['id']?>"><input name="amount" type="number" min="0.01" max="<?=e((string)$due)?>" step="0.01" placeholder="Amount" required><input name="note" placeholder="Note"><button class="btn">Pay</button></form><?php else:?>Paid<?php endif;?></td></tr><?php endforeach;?></table></div></section><section class="panel"><h2>Payment History</h2><div class="bulk"><table><tr><th>Date</th><th>Supplier</th><th>Amount</th><th>Reference</th><th>Note</th></tr><?php foreach($payments as $p):?><tr><td><?=e($p['created_at'])?></td><td><?=e($p['supplier'])?></td><td>Rs. <?=money((float)$p['amount'])?></td><td><?=e($p['invoice_no']??'Supplier account')?></td><td><?=e($p['note']??'')?></td></tr><?php endforeach;?></table></div></section></main><script>const body=document.getElementById('new');function row(){const tr=document.createElement('tr');tr.innerHTML='<td><input data-k="name" placeholder="Supplier name"></td><td><input data-k="phone" placeholder="Phone"></td><td><input data-k="address" placeholder="Address"></td><td><button type="button" class="remove" onclick="this.closest(\'tr\').remove()">×</button></td>';body.appendChild(tr)}document.getElementById('add').onclick=row;document.getElementById('save').onclick=()=>{const rows=[...body.children].map(tr=>{const o={};tr.querySelectorAll('[data-k]').forEach(x=>o[x.dataset.k]=x.value);return o}).filter(x=>x.name.trim());if(!rows.length)return alert('Add at least one supplier.');const f=document.createElement('form');f.method='post';f.innerHTML='<input name="action" value="bulk_add"><input name="rows">';f.querySelector('[name=rows]').value=JSON.stringify(rows);document.body.appendChild(f);f.submit()};row();row();</script></body></html>